-- RLS Policies for FULKRO tenant isolation
-- Generated by scripts/create_rls_policies.py
-- Per v2.1 Parte 4.3: RLS on all tables with client_id or project_id

ALTER TABLE audit_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_sessions FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS project_isolation ON audit_sessions;
CREATE POLICY project_isolation ON audit_sessions
  USING (project_id = current_project_id());

